"use client"

import type { SVGProps } from "react"

import { cn } from "@/lib/utils"
import { arcBox } from "./math"

import { GaugeContext, useGaugeContextValue } from "./context"
import type { GaugeDomainProps } from "./context"

/** See `GaugeProps.fit`. */
export type GaugeFit = "square" | "content"

export type GaugeProps = Omit<SVGProps<SVGSVGElement>, "viewBox"> &
  GaugeDomainProps & {
    /** Extra room around the reference circle for thick strokes, ticks and labels. */
    padding?: number
    /**
     * How the SVG box is sized. `square` boxes the whole circle, so a half gauge
     * reserves the room a full one would. `content` fits the box to the arc's own
     * sweep and sets a matching `aspect-ratio`, so the dial fills the width it is
     * given. `padding` is still what makes room for ticks, labels and value text,
     * since those are drawn by children the root cannot measure.
     */
    fit?: GaugeFit
  }

/**
 * Root of a composable gauge. Renders a square SVG centred on the origin and
 * publishes the value, domain and geometry to any primitive rendered inside.
 */
export const Gauge = ({
  value,
  min,
  max,
  startAngle,
  endAngle,
  radius,
  transition,
  initialValue,
  padding = 48,
  fit = "square",
  className,
  style,
  children,
  ...props
}: GaugeProps) => {
  const gauge = useGaugeContextValue({
    value,
    min,
    max,
    startAngle,
    endAngle,
    radius,
    transition,
    initialValue,
  })

  const half = gauge.radius + padding
  const box =
    fit === "content"
      ? arcBox(gauge.radius, gauge.startAngle, gauge.endAngle, padding)
      : { x: -half, y: -half, width: 2 * half, height: 2 * half }

  return (
    <GaugeContext.Provider value={gauge}>
      <svg
        viewBox={`${box.x} ${box.y} ${box.width} ${box.height}`}
        preserveAspectRatio="xMidYMid meet"
        /* A fitted box takes its height from its width, so it needs the ratio
           on the element; a square one fills whatever box it is handed. */
        style={
          fit === "content"
            ? { aspectRatio: `${box.width} / ${box.height}`, ...style }
            : style
        }
        className={cn(
          "overflow-visible",
          fit === "content" ? "max-h-full w-full" : "h-full w-full",
          className
        )}
        {...props}
      >
        {children}
      </svg>
    </GaugeContext.Provider>
  )
}

"use client"

import { createContext, useContext } from "react"

import { clamp, valueToAngle } from "./math"
import type { GaugeTransition } from "./transition"
import { useAnimatedValue } from "./use-animated-value"

export type GaugeContextValue = {
  /** Value being drawn this frame, clamped to the domain. Animated when the
      gauge has a transition. */
  value: number
  /** Value the gauge is heading for; equals `value` once settled. */
  target: number
  min: number
  max: number
  startAngle: number
  endAngle: number
  /** Radius of the gauge's reference circle in SVG units. */
  radius: number
  /** Maps a domain value onto a gauge angle. */
  angleOf: (value: number) => number
}

export const GaugeContext = createContext<GaugeContextValue | null>(null)

export const useGauge = () => {
  const ctx = useContext(GaugeContext)
  if (!ctx) {
    throw new Error("Gauge primitives must be rendered inside <Gauge>.")
  }
  return ctx
}

/** The domain, geometry and animation every gauge root takes. */
export type GaugeDomainProps = {
  value: number
  min?: number
  max?: number
  /** Gauge degrees, clockwise from six o'clock. */
  startAngle?: number
  endAngle?: number
  /** Reference radius in SVG units. Every child positions itself against this. */
  radius?: number
  /**
   * Animate towards new values. `true` uses a gentle spring; pass a
   * `GaugeTransition` to tune it or switch to a timed tween. Omit for
   * instant updates.
   */
  transition?: GaugeTransition | boolean
  /** Where the value starts on mount when animating, for a sweep-in effect. */
  initialValue?: number
}

/**
 * Resolves the domain and follows the value, returning the context a gauge
 * root publishes to its children. Shared by `Gauge` and `GaugeInset` so a
 * gauge nested inside another animates and maps values exactly like a
 * top-level one, and so the defaults live in one place.
 */
export const useGaugeContextValue = ({
  value,
  min = 0,
  max = 100,
  startAngle = 40,
  endAngle = 320,
  radius = 200,
  transition,
  initialValue,
}: GaugeDomainProps): GaugeContextValue => {
  const lo = Math.min(min, max)
  const hi = Math.max(min, max)
  const target = clamp(value, lo, hi)
  const shown = useAnimatedValue(
    target,
    transition,
    hi - lo,
    initialValue === undefined ? undefined : clamp(initialValue, lo, hi)
  )

  return {
    value: shown,
    target,
    min,
    max,
    startAngle,
    endAngle,
    radius,
    angleOf: (v) => valueToAngle(v, min, max, startAngle, endAngle),
  }
}

"use client"

import { arcPath, polar } from "./math"
import type { StrokeCap, Zone } from "./utils"

import { useGauge } from "./context"

type ArcStyleProps = {
  width?: number
  color?: string
  opacity?: number
  cap?: StrokeCap
  /** Radial offset from the reference radius. Positive moves outward. */
  offset?: number
}

/** The full background arc from `startAngle` to `endAngle`. */
export const GaugeTrack = ({
  width = 24,
  color = "currentColor",
  opacity = 0.15,
  cap = "round",
  offset = 0,
}: ArcStyleProps) => {
  const { radius, startAngle, endAngle } = useGauge()
  return (
    <path
      d={arcPath(radius + offset, startAngle, endAngle)}
      fill="none"
      stroke={color}
      strokeOpacity={opacity}
      strokeWidth={width}
      strokeLinecap={cap}
    />
  )
}

export type GaugeArcProps = ArcStyleProps & {
  /** Domain value the arc starts at. Defaults to `min`. */
  from?: number
  /** Domain value the arc ends at. Defaults to the current value. */
  to?: number
  /**
   * Grow the arc back from the end of the sweep instead of forward from its
   * start. The length is the same; only the end it is anchored to changes,
   * which is what a dial filling towards its start needs.
   */
  reverse?: boolean
}

/** The filled arc, from `min` (or `from`) up to the current value (or `to`). */
export const GaugeArc = ({
  width = 24,
  color = "currentColor",
  opacity = 1,
  cap = "round",
  offset = 0,
  from,
  to,
  reverse = false,
}: GaugeArcProps) => {
  const { radius, min, max, value, angleOf } = useGauge()
  const tail = from ?? min
  const head = to ?? value
  const [a0, a1] = reverse
    ? [angleOf(max - (head - tail)), angleOf(max)]
    : [angleOf(tail), angleOf(head)]
  if (a1 <= a0) return null

  return (
    <path
      d={arcPath(radius + offset, a0, a1)}
      fill="none"
      stroke={color}
      strokeOpacity={opacity}
      strokeWidth={width}
      strokeLinecap={cap}
    />
  )
}

export type GaugeZonesProps = Omit<ArcStyleProps, "color"> & {
  /**
   * Ordered cutoffs. Each zone runs from the previous zone's `to` (or `min`)
   * up to its own `to`; the last zone always extends to `max`.
   */
  zones: Zone[]
  /** Gap between neighbouring zones, in degrees. */
  gap?: number
  /**
   * Cap on the two outer ends of the whole band (the start of the first zone
   * and the end of the last). `cap` covers the joints between zones. Defaults
   * to `cap`, so a single value still rounds or squares every end.
   */
  endCap?: StrokeCap
}

/** Coloured bands marking the cutoffs of the domain. */
export const GaugeZones = ({
  zones,
  width = 8,
  opacity = 1,
  cap = "butt",
  endCap = cap,
  offset = 0,
  gap = 0,
}: GaugeZonesProps) => {
  const { radius, min, max, angleOf } = useGauge()
  if (zones.length === 0) return null

  const r = radius + offset
  /* Segments are drawn with butt caps and rounded where asked with a disc of
     the stroke width, which is exactly the shape a round cap adds. Drawing
     the discs separately lets the joints and the outer ends differ. */
  const dot = (angle: number, color: string, key: string) => {
    const { x, y } = polar(r, angle)
    return <circle key={key} cx={x} cy={y} r={width / 2} fill={color} />
  }

  /* Each zone runs from the previous cutoff to its own, clamped to the domain. */
  const segments = zones.reduce<{ from: number; to: number }[]>(
    (acc, zone, i) => {
      const from = i === 0 ? min : acc[i - 1].to
      const isLast = i === zones.length - 1
      const to = isLast ? max : Math.min(Math.max(zone.to, from), max)
      acc.push({ from, to })
      return acc
    },
    []
  )

  return (
    <g opacity={opacity}>
      {zones.map((zone, i) => {
        const isFirst = i === 0
        const isLast = i === zones.length - 1
        const { from, to } = segments[i]
        const a0 = angleOf(from) + (isFirst ? 0 : gap / 2)
        const a1 = angleOf(to) - (isLast ? 0 : gap / 2)
        if (a1 <= a0) return null
        const startCap = isFirst ? endCap : cap
        const finishCap = isLast ? endCap : cap
        return (
          <g key={i}>
            <path
              d={arcPath(r, a0, a1)}
              fill="none"
              stroke={zone.color}
              strokeWidth={width}
              strokeLinecap="butt"
            />
            {startCap === "round" && dot(a0, zone.color, "start")}
            {finishCap === "round" && dot(a1, zone.color, "end")}
          </g>
        )
      })}
    </g>
  )
}

"use client"

import { cn } from "@/lib/utils"
import { polar, stepValues } from "./math"
import type { GaugeContextValue } from "./context"
import {
  fontClass,
  weightClass,
  type FontFamily,
  type FontWeight,
  type StrokeCap,
} from "./utils"

import { useGauge } from "./context"

/**
 * Evenly spaced domain values for ticks. On a closed ring the last step lands
 * on the first, so it is dropped rather than drawn twice.
 */
const tickValues = (
  { min, max, startAngle, endAngle }: GaugeContextValue,
  count: number
) => {
  const values = stepValues(min, max, count)
  if (endAngle - startAngle >= 360) values.pop()
  return values
}

type RadialLineProps = {
  /** Length of each line along the radius. */
  length?: number
  width?: number
  color?: string
  opacity?: number
  cap?: StrokeCap
  /** Radial offset of the line's midpoint from the reference radius. */
  offset?: number
}

const RadialLines = ({
  angles,
  length = 12,
  width = 2,
  color = "currentColor",
  opacity = 1,
  cap = "round",
  offset = 0,
}: RadialLineProps & { angles: number[] }) => {
  const { radius } = useGauge()
  const inner = radius + offset - length / 2
  const outer = radius + offset + length / 2

  return (
    <g
      stroke={color}
      strokeOpacity={opacity}
      strokeWidth={width}
      strokeLinecap={cap}
    >
      {angles.map((angle, i) => {
        const a = polar(inner, angle)
        const b = polar(outer, angle)
        return <line key={i} x1={a.x} y1={a.y} x2={b.x} y2={b.y} />
      })}
    </g>
  )
}

export type GaugeTicksProps = RadialLineProps & {
  /** Number of intervals across the domain; renders `count + 1` ticks. */
  count?: number
}

/** Evenly spaced tick marks across the whole arc. */
export const GaugeTicks = ({ count = 10, ...props }: GaugeTicksProps) => {
  const gauge = useGauge()
  const angles = tickValues(gauge, count).map(gauge.angleOf)
  return <RadialLines angles={angles} {...props} />
}

export type GaugeMarksProps = RadialLineProps & {
  /** Domain values to mark, for example the cutoffs between zones. */
  values: number[]
}

/** Radial marks at arbitrary domain values. */
export const GaugeMarks = ({ values, ...props }: GaugeMarksProps) => {
  const { angleOf } = useGauge()
  return <RadialLines angles={values.map(angleOf)} {...props} />
}

export type GaugeTickLabelsProps = {
  count?: number
  /** Radial offset of the label centre from the reference radius. */
  offset?: number
  fontSize?: number
  color?: string
  font?: FontFamily
  weight?: FontWeight
  decimals?: number
  format?: (value: number) => string
}

/** Numeric labels at evenly spaced values across the arc. */
export const GaugeTickLabels = ({
  count = 10,
  offset = -48,
  fontSize = 16,
  color = "currentColor",
  font = "sans",
  weight = "medium",
  decimals = 0,
  format,
}: GaugeTickLabelsProps) => {
  const gauge = useGauge()
  const { radius, angleOf } = gauge
  const values = tickValues(gauge, count)

  return (
    <g
      fill={color}
      fontSize={fontSize}
      textAnchor="middle"
      dominantBaseline="central"
      className={cn(fontClass[font], weightClass[weight], "tabular-nums")}
    >
      {values.map((value, i) => {
        const p = polar(radius + offset, angleOf(value))
        return (
          <text key={i} x={p.x} y={p.y}>
            {format ? format(value) : value.toFixed(decimals)}
          </text>
        )
      })}
    </g>
  )
}

"use client"

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import {
  fontClass,
  weightClass,
  type FontFamily,
  type FontWeight,
  type TextAnchor,
} from "./utils"

import { useGauge } from "./context"

export type GaugeTextProps = {
  /** Position relative to the gauge centre in SVG units. Positive y is down. */
  x?: number
  y?: number
  fontSize?: number
  color?: string
  font?: FontFamily
  weight?: FontWeight
  anchor?: TextAnchor
  className?: string
  children: ReactNode
}

/** A free-standing label anywhere on the gauge. */
export const GaugeText = ({
  x = 0,
  y = 0,
  fontSize = 24,
  color = "currentColor",
  font = "sans",
  weight = "medium",
  anchor = "middle",
  className,
  children,
}: GaugeTextProps) => (
  <text
    x={x}
    y={y}
    fill={color}
    fontSize={fontSize}
    textAnchor={anchor}
    dominantBaseline="central"
    className={cn(fontClass[font], weightClass[weight], className)}
  >
    {children}
  </text>
)

export type GaugeValueProps = Omit<GaugeTextProps, "children"> & {
  decimals?: number
  format?: (value: number) => string
}

/** The current value as text. */
export const GaugeValue = ({
  decimals = 0,
  format,
  className,
  fontSize = 96,
  weight = "semibold",
  ...props
}: GaugeValueProps) => {
  const { value } = useGauge()
  return (
    <GaugeText
      fontSize={fontSize}
      weight={weight}
      className={cn("tabular-nums", className)}
      {...props}
    >
      {format ? format(value) : value.toFixed(decimals)}
    </GaugeText>
  )
}

"use client"

import { polar, valueToTurnedAngle } from "./math"
import type { NeedleStyle } from "./utils"

import { useGauge } from "./context"

export type GaugeNeedleProps = {
  /**
   * `line` is a stroke with round ends, `pointer` a tapered blade that is
   * widest at the centre and ends in a rounded tip, and `compass` a lozenge
   * whose two halves can take different colours.
   */
  style?: NeedleStyle
  /** Length as a fraction of the reference radius. */
  length?: number
  /** Stroke width for `line`; width at the centre for the filled styles. */
  width?: number
  color?: string
  /** How far the needle extends behind the centre, in SVG units. */
  tail?: number
  /** Colour of the tail half of a `pointer` or `compass`. Defaults to `color`. */
  tailColor?: string
  /**
   * Sweeps of the arc the needle makes across the domain. A clock's minute
   * hand turns 12 times while the hour hand turns once.
   */
  turns?: number
}

const pts = (points: { x: number; y: number }[]) =>
  points.map((p) => `${p.x},${p.y}`).join(" ")

/** A needle pointing at the current value. Add a `GaugeHub` for the pivot. */
export const GaugeNeedle = ({
  style = "line",
  length = 0.85,
  width = 6,
  color = "currentColor",
  tail = 30,
  tailColor = color,
  turns = 1,
}: GaugeNeedleProps) => {
  const { radius, value, min, max, startAngle, endAngle } = useGauge()

  const angle = valueToTurnedAngle(value, min, max, startAngle, endAngle, turns)

  const tip = polar(radius * length, angle)
  const back = polar(-tail, angle)

  if (style === "line") {
    return (
      <line
        x1={back.x}
        y1={back.y}
        x2={tip.x}
        y2={tip.y}
        stroke={color}
        strokeWidth={width}
        strokeLinecap="round"
      />
    )
  }

  /* The filled styles are two polygons meeting at the centre, so the tail can
     take its own colour. Their shared base runs across the pivot. Both ends
     keep a fifth of the width and are rounded off with a disc of that size,
     as a round cap would, so a thin needle never vanishes to a point. */
  const left = polar(width / 2, angle - 90)
  const right = polar(width / 2, angle + 90)
  const endRadius = width * 0.2
  const endLeft = polar(endRadius, angle - 90)
  const endRight = polar(endRadius, angle + 90)
  const blade = (end: { x: number; y: number }) =>
    pts([
      { x: end.x + endLeft.x, y: end.y + endLeft.y },
      { x: end.x + endRight.x, y: end.y + endRight.y },
      right,
      left,
    ])

  /* A pointer's tail is a blunt stub; a compass tapers the same both ways. */
  const rear =
    style === "compass"
      ? blade(back)
      : pts([
          { x: back.x + left.x * 0.6, y: back.y + left.y * 0.6 },
          { x: back.x + right.x * 0.6, y: back.y + right.y * 0.6 },
          right,
          left,
        ])

  return (
    <g>
      {tail > 0 && <polygon points={rear} fill={tailColor} />}
      {tail > 0 && style === "compass" && (
        <circle cx={back.x} cy={back.y} r={endRadius} fill={tailColor} />
      )}
      <polygon points={blade(tip)} fill={color} />
      <circle cx={tip.x} cy={tip.y} r={endRadius} fill={color} />
    </g>
  )
}

export type GaugeHubProps = {
  radius?: number
  color?: string
}

/** The pivot disc at the centre, drawn once however many needles there are. */
export const GaugeHub = ({
  radius = 12,
  color = "currentColor",
}: GaugeHubProps) => (radius > 0 ? <circle r={radius} fill={color} /> : null)

"use client"

import { polar, valueToTurnedAngle } from "./math"

import { useGauge } from "./context"

export type GaugeDotProps = {
  /** Radius of the dot itself, in SVG units. */
  radius?: number
  color?: string
  opacity?: number
  /** Radial offset of the dot's centre from the reference radius. */
  offset?: number
  /**
   * Sweeps of the arc the dot makes across the domain, as `GaugeNeedle.turns`:
   * two sends it round twice while the value crosses the domain once.
   */
  turns?: number
}

/**
 * A disc riding the arc at the current value: the head of a progress ring, a
 * body on its orbit, the handle on a dial. `GaugeMarks` stands at fixed values
 * and points along the radius; this follows the value the way a needle does,
 * and is round at any size a stroke cap could not reach.
 */
export const GaugeDot = ({
  radius = 10,
  color = "currentColor",
  opacity = 1,
  offset = 0,
  turns = 1,
}: GaugeDotProps) => {
  const gauge = useGauge()
  const angle = valueToTurnedAngle(
    gauge.value,
    gauge.min,
    gauge.max,
    gauge.startAngle,
    gauge.endAngle,
    turns
  )
  const { x, y } = polar(gauge.radius + offset, angle)

  return <circle cx={x} cy={y} r={radius} fill={color} fillOpacity={opacity} />
}

/**
 * Pure geometry for the gauge primitives.
 *
 * Angles are "gauge degrees": 0 points straight down (six o'clock) and
 * values increase clockwise, so a sweep from 40° to 320° leaves an opening
 * at the bottom. Coordinates are SVG units centred on the gauge origin.
 */

export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

export const degreesToRadians = (degrees: number) => (degrees * Math.PI) / 180

/**
 * Point on a circle of `radius` at a gauge angle. Coordinates are rounded so
 * server and client render identical attributes and hydration stays clean.
 */
export const polar = (radius: number, angle: number) => {
  const theta = degreesToRadians(angle + 90)
  return {
    x: round(radius * Math.cos(theta)),
    y: round(radius * Math.sin(theta)),
  }
}

const round = (n: number) => Math.round(n * 1000) / 1000

/** Linear map of a value in [min, max] onto the arc [startAngle, endAngle]. */
export const valueToAngle = (
  value: number,
  min: number,
  max: number,
  startAngle: number,
  endAngle: number
) => {
  const span = max - min
  const t = span === 0 ? 0 : (clamp(value, min, max) - min) / span
  return startAngle + t * (endAngle - startAngle)
}

/**
 * Angle for a value that wraps the arc more than once. A single turn maps the
 * domain onto the sweep exactly as `valueToAngle` does; past that each turn
 * runs the sweep again from its start, which is how a clock's minute hand
 * gets round twelve times while the hour hand goes round once.
 */
export const valueToTurnedAngle = (
  value: number,
  min: number,
  max: number,
  startAngle: number,
  endAngle: number,
  turns: number
) => {
  if (turns === 1) return valueToAngle(value, min, max, startAngle, endAngle)
  const span = max - min
  const t = span === 0 ? 0 : (value - min) / span
  return startAngle + ((t * turns) % 1) * (endAngle - startAngle)
}

/**
 * SVG path for an arc of `radius` from `from` to `to` gauge degrees. Sweeps
 * over 180° are split so a single `A` command never has to disambiguate a
 * large arc, which also makes a full 360° circle render correctly.
 */
export const arcPath = (radius: number, from: number, to: number) => {
  const sweep = Math.min(to - from, 360)
  if (sweep <= 0 || radius <= 0) return ""

  const pieces = Math.max(1, Math.ceil(sweep / 180))
  const step = sweep / pieces
  const start = polar(radius, from)
  const parts = [`M ${fmt(start.x)} ${fmt(start.y)}`]

  for (let i = 1; i <= pieces; i++) {
    const p = polar(radius, from + step * i)
    parts.push(`A ${fmt(radius)} ${fmt(radius)} 0 0 1 ${fmt(p.x)} ${fmt(p.y)}`)
  }

  return parts.join(" ")
}

/**
 * Tight bounding box of an arc sweep, inflated by `padding`. Takes the two
 * endpoints, every quarter turn the sweep crosses, and the origin, so a gauge
 * that pivots a needle keeps its hub inside the box. A sweep that closes on
 * itself crosses all four quarters and lands back on the full square.
 */
export const arcBox = (
  radius: number,
  from: number,
  to: number,
  padding = 0
) => {
  const sweep = clamp(to - from, 0, 360)
  const end = from + sweep
  const points = [{ x: 0, y: 0 }, polar(radius, from), polar(radius, end)]
  for (let a = Math.ceil(from / 90) * 90; a <= end; a += 90) {
    points.push(polar(radius, a))
  }

  const xs = points.map((p) => p.x)
  const ys = points.map((p) => p.y)
  const x = round(Math.min(...xs) - padding)
  const y = round(Math.min(...ys) - padding)

  return {
    x,
    y,
    width: round(Math.max(...xs) + padding - x),
    height: round(Math.max(...ys) + padding - y),
  }
}

/** Evenly spaced values across the domain, inclusive of both ends. */
export const stepValues = (min: number, max: number, intervals: number) => {
  const n = Math.max(1, Math.round(intervals))
  return Array.from({ length: n + 1 }, (_, i) => min + ((max - min) * i) / n)
}

const fmt = (n: number) => Number(n.toFixed(3)).toString()

/**
 * Dependency-free value animation for the gauge: a damped spring and a
 * cubic-bezier tween, both stepped per frame. Pure functions only; the hook
 * that drives them lives in `use-animated-value.ts`.
 */

/** A named curve, CSS-style cubic-bezier control points, or your own function. */
export type GaugeEasing =
  | "linear"
  | "easeIn"
  | "easeOut"
  | "easeInOut"
  | [number, number, number, number]
  | ((t: number) => number)

export type GaugeSpringTransition = {
  type: "spring"
  /** Physics parameters. When any is given they take precedence over the
      perceptual `visualDuration` and `bounce` pair. */
  stiffness?: number
  damping?: number
  mass?: number
  /** Seconds the spring visibly takes to reach the target. Default 0.5. */
  visualDuration?: number
  /** 0 settles without overshoot, 1 rings freely. Default 0.1. */
  bounce?: number
}

export type GaugeTweenTransition = {
  type: "tween"
  /** Seconds. Default 0.5. */
  duration?: number
  /** Default "easeInOut". */
  ease?: GaugeEasing
}

export type GaugeTransition = GaugeSpringTransition | GaugeTweenTransition

export const DEFAULT_TRANSITION: GaugeSpringTransition = {
  type: "spring",
  visualDuration: 0.5,
  bounce: 0.1,
}

/** Turns the `transition` prop into a concrete config, or null when off. */
export const resolveTransition = (
  transition: GaugeTransition | boolean | undefined
): GaugeTransition | null => {
  if (!transition) return null
  return transition === true ? DEFAULT_TRANSITION : transition
}

/* ---------- spring ---------- */

export type SpringPhysics = { stiffness: number; damping: number; mass: number }

/**
 * Physics for a spring config. The perceptual pair maps onto stiffness and
 * damping the same way the motion library does, so a spring tuned against
 * that library feels the same here.
 */
export const springPhysics = (t: GaugeSpringTransition): SpringPhysics => {
  const hasPhysics =
    t.stiffness !== undefined || t.damping !== undefined || t.mass !== undefined
  if (hasPhysics) {
    return {
      stiffness: t.stiffness ?? 100,
      damping: t.damping ?? 10,
      mass: t.mass ?? 1,
    }
  }
  const visualDuration = t.visualDuration ?? 0.5
  const bounce = t.bounce ?? 0.1
  const root = (2 * Math.PI) / (visualDuration * 1.2)
  const stiffness = root * root
  const ratio = Math.min(1, Math.max(0.05, 1 - bounce))
  return { stiffness, damping: 2 * ratio * Math.sqrt(stiffness), mass: 1 }
}

export type SpringState = { value: number; velocity: number }

const SUBSTEP = 1 / 240

/**
 * Advances a spring by `dt` seconds towards `target` with semi-implicit
 * Euler in small substeps, which stays stable for stiff springs. Returns the
 * new state and whether it has come to rest within `precision`.
 */
export const stepSpring = (
  state: SpringState,
  target: number,
  physics: SpringPhysics,
  dt: number,
  precision: number
): { state: SpringState; done: boolean } => {
  let { value, velocity } = state
  let remaining = Math.min(dt, 0.064)
  while (remaining > 0) {
    const h = Math.min(SUBSTEP, remaining)
    const force =
      -physics.stiffness * (value - target) - physics.damping * velocity
    velocity += (force / physics.mass) * h
    value += velocity * h
    remaining -= h
  }
  const done =
    Math.abs(value - target) < precision && Math.abs(velocity) < precision * 10
  return done
    ? { state: { value: target, velocity: 0 }, done }
    : { state: { value, velocity }, done }
}

/* ---------- tween ---------- */

const namedCurves: Record<
  Exclude<
    GaugeEasing,
    [number, number, number, number] | ((t: number) => number)
  >,
  [number, number, number, number]
> = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
}

/** A CSS-compatible cubic-bezier easing function. */
export const cubicBezier = (x1: number, y1: number, x2: number, y2: number) => {
  const bezier = (t: number, p1: number, p2: number) => {
    const u = 1 - t
    return 3 * u * u * t * p1 + 3 * u * t * t * p2 + t * t * t
  }
  const slope = (t: number, p1: number, p2: number) => {
    const u = 1 - t
    return 3 * u * u * p1 + 6 * u * t * (p2 - p1) + 3 * t * t * (1 - p2)
  }
  return (x: number) => {
    if (x <= 0) return 0
    if (x >= 1) return 1
    // Newton's method, falling back to bisection where the curve is flat.
    let t = x
    for (let i = 0; i < 8; i++) {
      const dx = bezier(t, x1, x2) - x
      const d = slope(t, x1, x2)
      if (Math.abs(dx) < 1e-6) return bezier(t, y1, y2)
      if (Math.abs(d) < 1e-6) break
      t -= dx / d
    }
    let lo = 0
    let hi = 1
    t = x
    while (hi - lo > 1e-6) {
      if (bezier(t, x1, x2) < x) lo = t
      else hi = t
      t = (lo + hi) / 2
    }
    return bezier(t, y1, y2)
  }
}

/** Resolves any `GaugeEasing` into a function of progress. */
export const easingFunction = (ease: GaugeEasing = "easeInOut") => {
  if (typeof ease === "function") return ease
  const [x1, y1, x2, y2] = Array.isArray(ease) ? ease : namedCurves[ease]
  return cubicBezier(x1, y1, x2, y2)
}

"use client"

import { useEffect, useRef, useState } from "react"

import {
  easingFunction,
  resolveTransition,
  springPhysics,
  stepSpring,
  type GaugeTransition,
  type SpringState,
} from "./transition"

/**
 * Follows `target` with the given transition and returns the value to draw
 * this frame. With no transition it returns `target` as is and renders
 * nothing extra. Honours `prefers-reduced-motion` by snapping.
 *
 * `span` is the size of the domain and sets the rest threshold. `initial` is
 * where the value starts on mount, for a sweep-in from the minimum.
 */
export const useAnimatedValue = (
  target: number,
  transition: GaugeTransition | boolean | undefined,
  span: number,
  initial?: number
) => {
  const enabled = Boolean(transition)
  const [display, setDisplay] = useState(initial ?? target)
  const spring = useRef<SpringState>({ value: initial ?? target, velocity: 0 })

  // The config is read through a ref so an inline object or easing function
  // does not restart the animation every render; only its content matters.
  const transitionRef = useRef(transition)
  useEffect(() => {
    transitionRef.current = transition
  })
  const configKey = JSON.stringify(transition)

  // While disabled, keep the spring state in step so re-enabling animates
  // from what is on screen rather than from a stale value.
  useEffect(() => {
    if (!enabled) spring.current = { value: target, velocity: 0 }
  }, [enabled, target])

  useEffect(() => {
    const config = resolveTransition(transitionRef.current)
    if (!config) return
    const precision = Math.max(span, 1e-6) * 1e-4
    const snap = prefersReducedMotion()

    let frame = 0
    let last = performance.now()
    const from = spring.current.value
    const start = last

    const tick = (now: number) => {
      const dt = (now - last) / 1000
      last = now
      let done: boolean

      if (snap) {
        spring.current = { value: target, velocity: 0 }
        done = true
      } else if (config.type === "spring") {
        const physics = springPhysics(config)
        const next = stepSpring(spring.current, target, physics, dt, precision)
        spring.current = next.state
        done = next.done
      } else {
        const duration = Math.max(config.duration ?? 0.5, 1e-3)
        const progress = Math.min((now - start) / 1000 / duration, 1)
        const eased = easingFunction(config.ease)(progress)
        const value = from + (target - from) * eased
        spring.current = { value, velocity: 0 }
        done = progress >= 1
      }

      setDisplay(spring.current.value)
      if (!done) frame = requestAnimationFrame(tick)
    }

    frame = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(frame)
  }, [target, configKey, span])

  return enabled ? display : target
}

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches
